export type ExerciseCategory =
  | "freehand"
  | "gym"
  | "calisthenics"
  | "martial_arts"
  | "yoga"
  | "cardio"
  | "rehab";

export type DifficultyLevel = "beginner" | "intermediate" | "advanced";

export type Equipment =
  | "none"
  | "dumbbell"
  | "barbell"
  | "machine"
  | "band"
  | "kettlebell"
  | "cable"
  | "mat"
  | "pullup_bar"
  | "parallel_bars"
  | "rings"
  | "bag"
  | "rope";

export type MovementPattern =
  | "push"
  | "pull"
  | "squat"
  | "hinge"
  | "rotation"
  | "strike"
  | "hold"
  | "carry"
  | "cardio"
  | "mobility"
  | "balance";

export interface Exercise {
  id: string;
  name: string;
  category: ExerciseCategory;
  subcategory: string;
  equipment: Equipment[];
  movement_pattern: MovementPattern;
  muscle_groups: string[];
  targetMuscles: string[];
  difficulty: DifficultyLevel;
  is_compound: boolean;
  variations: string[];
  description: string;
  instructions: string[];
  caloriesPerRep: number;
  repDuration: number;
  met_value: number;
  icon: string;
  color: string;
}

export interface ExerciseGroup {
  subcategory: string;
  exercises: Exercise[];
}

const CAT_COLOR: Record<ExerciseCategory, string> = {
  freehand: "#00FF88",
  gym: "#FF6B35",
  calisthenics: "#A855F7",
  martial_arts: "#EF4444",
  yoga: "#10B981",
  cardio: "#06B6D4",
  rehab: "#8B5CF6",
};

const CAT_ICON: Record<ExerciseCategory, string> = {
  freehand: "body-outline",
  gym: "barbell-outline",
  calisthenics: "fitness-outline",
  martial_arts: "flame-outline",
  yoga: "leaf-outline",
  cardio: "flash-outline",
  rehab: "shield-checkmark-outline",
};

function ex(
  id: string,
  name: string,
  cat: ExerciseCategory,
  sub: string,
  equip: Equipment[],
  mp: MovementPattern,
  muscles: string[],
  diff: DifficultyLevel,
  compound: boolean,
  cal: number,
  met: number,
): Exercise {
  return {
    id, name, category: cat, subcategory: sub,
    equipment: equip, movement_pattern: mp,
    muscle_groups: muscles, targetMuscles: muscles,
    difficulty: diff, is_compound: compound,
    variations: [],
    description: `${name} — targets ${muscles[0]}.`,
    instructions: [
      "Maintain control throughout the movement",
      "Breathe out on the exertion phase",
      "Keep proper form and posture",
    ],
    caloriesPerRep: cal, repDuration: 3, met_value: met,
    icon: CAT_ICON[cat], color: CAT_COLOR[cat],
  };
}

